sp_widget.client_script:
api.controller = function($rootScope) {
    var c = this;

    c.filterTable = function(kpi) {
        if (c.data.userRole === 'supervisor' && kpi.filter !== undefined) {
            $rootScope.$broadcast('wei.filterTable', { filter: kpi.filter, label: kpi.label });
        }
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=DM+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --wei-bg:         #EEECEA;
  --wei-primary:    #5B4BF5;
  --wei-primary-dk: #4438D6;
  --wei-primary-lt: #EAE8FE;
  --wei-text:       #0F0F0F;
  --wei-muted:      #6B6B6B;
  --wei-border:     #D8D4D0;
  --wei-card:       #FFFFFF;
  --wei-radius:     12px;
  --wei-shadow:     0 2px 12px rgba(91,75,245,0.08);
  --wei-success:    #22C55E;
  --wei-warning:    #F59E0B;
  --wei-danger:     #EF4444;
  --wei-info:       #3B82F6;
  --ff-head:        'Playfair Display', Georgia, serif;
  --ff-body:        'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

body, .sp-widget, .portal-page {
  font-family: var(--ff-body) !important;
  background-color: var(--wei-bg) !important;
  color: var(--wei-text) !important;
}

h1,h2,h3,h4,h5,h6 {
  font-family: var(--ff-head) !important;
}

.kpi-dashboard-wrapper { margin-bottom: 24px; }

.dashboard-title {
  font-family: var(--ff-head) !important;
  font-size: 26px;
  font-weight: 800;
  color: var(--wei-text);
  margin: 0 0 6px;
}
.dashboard-subtitle {
  font-size: 13px;
  color: var(--wei-muted);
  font-family: var(--ff-body);
  margin-bottom: 24px;
}

.kpi-card {
  border-radius: var(--wei-radius);
  padding: 22px 16px;
  text-align: center;
  margin-bottom: 16px;
  color: #fff;
  box-shadow: var(--wei-shadow);
  transition: transform .2s, box-shadow .2s;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  background: var(--wei-primary) !important;
}
.kpi-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(91,75,245,0.2);
}
.kpi-card::before {
  content: '';
  position: absolute;
  top: -20px; right: -20px;
  width: 80px; height: 80px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
}
.kpi-number {
  font-family: var(--ff-head) !important;
  font-size: 38px;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 4px;
}
.kpi-label {
  font-family: var(--ff-body) !important;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  opacity: 0.85;
  margin: 0;
}
.kpi-icon {
  font-size: 22px;
  margin-bottom: 8px;
  opacity: 0.8;
}

/* Card color variants */
.kpi-card.kpi-blue   { background: #3B82F6 !important; }
.kpi-card.kpi-purple { background: var(--wei-primary) !important; }
.kpi-card.kpi-green  { background: #22C55E !important; }
.kpi-card.kpi-yellow { background: #F59E0B !important; }
.kpi-card.kpi-red    { background: #EF4444 !important; }
.kpi-card.kpi-gray   { background: #6B7280 !important; }
.kpi-card.kpi-teal   { background: #14B8A6 !important; }
.kpi-card.kpi-orange { background: #F97316 !important; }

.kpi-progress-bar {
  height: 4px;
  background: rgba(255,255,255,0.25);
  border-radius: 2px;
  margin-top: 10px;
  overflow: hidden;
}
.kpi-progress-fill {
  height: 100%;
  background: rgba(255,255,255,0.75);
  border-radius: 2px;
  transition: width .6s ease;
}

sp_widget.script:
(function() {
    data.kpis = [];
    data.userRole = 'staff';
    data.userName = gs.getUserDisplayName() || 'User';

    // Determine user role
    if (gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin')) {
        data.userRole = 'supervisor';
    } else if (gs.hasRole('x_1956908_wareho_0.technician')) {
        data.userRole = 'technician';
    } else {
        data.userRole = 'staff';
    }

    var userId = gs.getUserID();
    var tableName = 'x_1956908_wareho_0_exception';

    function getCount(additionalQuery) {
        var ga = new GlideAggregate(tableName);
        // Enforce strict role-based data partitioning on server
        if (data.userRole === 'staff') {
            ga.addQuery('reported_by', userId);
        } else if (data.userRole === 'technician') {
            ga.addQuery('assigned_to', userId);
        }
        if (additionalQuery) {
            ga.addEncodedQuery(additionalQuery);
        }
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) {
            return parseInt(ga.getAggregate('COUNT'), 10) || 0;
        }
        return 0;
    }

    if (data.userRole === 'supervisor') {
        // Supervisor: 7 specific KPI cards mandated by requirements
        var total = getCount('');
        var newCount = getCount('status=new');
        var unassignedCount = getCount('assigned_toISEMPTY^statusNOT INresolved,closed');
        var inProgressCount = getCount('status=in_progress');
        var onHoldCount = getCount('status=pending');
        var resolvedCount = getCount('statusINresolved,closed');
        var highSevCount = getCount('severityINcritical,high^statusNOT INresolved,closed');

        data.kpis = [
            { label: 'Total Exceptions', count: total, icon: 'fa-database', bgClass: 'kpi-total', filter: '' },
            { label: 'New', count: newCount, icon: 'fa-plus-circle', bgClass: 'kpi-new', filter: 'status=new' },
            { label: 'Unassigned', count: unassignedCount, icon: 'fa-user-times', bgClass: 'kpi-unassigned', filter: 'assigned_toISEMPTY^statusNOT INresolved,closed' },
            { label: 'In Progress', count: inProgressCount, icon: 'fa-cogs', bgClass: 'kpi-progress', filter: 'status=in_progress' },
            { label: 'On Hold', count: onHoldCount, icon: 'fa-pause-circle', bgClass: 'kpi-hold', filter: 'status=pending' },
            { label: 'Resolved', count: resolvedCount, icon: 'fa-check-circle', bgClass: 'kpi-resolved', filter: 'statusINresolved,closed' },
            { label: 'High Severity', count: highSevCount, icon: 'fa-exclamation-triangle', bgClass: 'kpi-critical', filter: 'severityINcritical,high' }
        ];

        // Visual breakdown stats for supervisor
        data.statusDistribution = {
            total: Math.max(1, total),
            newPct: Math.round((newCount / Math.max(1, total)) * 100),
            inProgressPct: Math.round((inProgressCount / Math.max(1, total)) * 100),
            onHoldPct: Math.round((onHoldCount / Math.max(1, total)) * 100),
            resolvedPct: Math.round((resolvedCount / Math.max(1, total)) * 100)
        };
    } else if (data.userRole === 'technician') {
        // Technician: Assigned workload
        var techTotal = getCount('');
        var techAssigned = getCount('status=assigned');
        var techInProgress = getCount('status=in_progress');
        var techOnHold = getCount('status=pending');
        var techResolved = getCount('statusINresolved,closed');
        var techCritical = getCount('severityINcritical,high^statusNOT INresolved,closed');

        data.kpis = [
            { label: 'My Assigned Total', count: techTotal, icon: 'fa-tasks', bgClass: 'kpi-total' },
            { label: 'New / Awaiting Work', count: techAssigned, icon: 'fa-clock-o', bgClass: 'kpi-new' },
            { label: 'In Progress', count: techInProgress, icon: 'fa-wrench', bgClass: 'kpi-progress' },
            { label: 'On Hold', count: techOnHold, icon: 'fa-pause-circle', bgClass: 'kpi-hold' },
            { label: 'Resolved', count: techResolved, icon: 'fa-check-circle', bgClass: 'kpi-resolved' },
            { label: 'Critical / High', count: techCritical, icon: 'fa-exclamation-triangle', bgClass: 'kpi-critical' }
        ];
    } else {
        // Staff: Personal submissions tracking
        var staffTotal = getCount('');
        var staffNew = getCount('status=new');
        var staffInProgress = getCount('statusINassigned,in_progress');
        var staffOnHold = getCount('status=pending');
        var staffResolved = getCount('statusINresolved,closed');

        data.kpis = [
            { label: 'My Total Reports', count: staffTotal, icon: 'fa-file-text-o', bgClass: 'kpi-total' },
            { label: 'Awaiting Triage', count: staffNew, icon: 'fa-inbox', bgClass: 'kpi-new' },
            { label: 'Being Resolved', count: staffInProgress, icon: 'fa-cogs', bgClass: 'kpi-progress' },
            { label: 'On Hold', count: staffOnHold, icon: 'fa-pause-circle', bgClass: 'kpi-hold' },
            { label: 'Resolved / Closed', count: staffResolved, icon: 'fa-check-circle', bgClass: 'kpi-resolved' }
        ];
    }
})();
